// --- ตรวจสอบรูปแบบข้อมูลอัตโนมัติ ---
let results = [];
const firstItem = $input.first().json;

if (firstItem.results && Array.isArray(firstItem.results)) {
    results = firstItem.results; 
} else {
    results = $input.all().map(item => item.json);
}

if (!results || results.length === 0) {
  throw new Error("ไม่พบข้อมูลบทเรียน (Chapter Not Found)");
}

// เรียงลำดับบท
results.sort((a, b) => {
  let numA = a.properties['Chapter No.']?.number;
  let numB = b.properties['Chapter No.']?.number;
  if (numA == null) numA = 999;
  if (numB == null) numB = 999;
  return numA - numB;
});

// Helper แปลง Google Drive URL เป็นรูปโดยตรง
function getDirectImageUrl(url) {
  if (!url) return '';
  const match = url.match(/\/d\/([a-zA-Z0-9_-]+)/) || url.match(/[?&]id=([a-zA-Z0-9_-]+)/);
  if (match && match[1]) {
    return `https://lh3.googleusercontent.com/d/${match[1]}`;
  }
  return url;
}

// Clean Title
function cleanChapterTitle(title) {
  if (!title) return '';
  return title.replace(/^(บทที่\s*\d+|บทนำ|Chapter\s*\d+|Introduction)[:\s.-]*/i, '').trim();
}

function cleanContentBody(content, cleanTitle, chapterNo) {
  if (!content) return '';
  let cleaned = content.trim();
  if (cleanTitle) {
    const escaped = cleanTitle.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    const pattern = new RegExp(
      `^(?:<h[1-4][^>]*>\\s*(?:บทที่\\s*\\d+[:\\s.-]*|${chapterNo}\\.?\\s*)?(?:${escaped})?\\s*<\\/h[1-4]>|#{1,4}\\s+(?:บทที่\\s*\\d+[:\\s.-]*|${chapterNo}\\.?\\s*)?(?:${escaped})?)\\s*\\n*`,
      'i'
    );
    cleaned = cleaned.replace(pattern, '').trim();
  }
  return cleaned;
}

function transformCrossReferences(content, chaptersList) {
  if (!content) return '';
  return content.replace(/\[(อ้างอิง|ดูเพิ่มเติม|อ่านต่อ)?[:\s]*(บทที่\s*(\d+))([^\]]*)\]/g, (match, prefix, chapLabel, numStr, rest) => {
    const num = parseInt(numStr, 10);
    const label = prefix ? `${prefix}: ${chapLabel}${rest}` : `${chapLabel}${rest}`;
    return `<a href="#chap_${num}" class="cross-ref-badge">🔗 ${label}</a>`;
  });
}

