// โครงร่างหน้าแรก
let fullHtml = `<!DOCTYPE html><html><head><meta charset="UTF-8"><title>Ebook Export</title><style>${style}</style></head><body>

<div class="cover">
  <div class="cover-badge">Official Publication</div>
  <h1>Ebook Draft Edition</h1>
  <h2>จัดทำและเรียบเรียงโดย Ebook Creator Studio</h2>
  <div class="cover-divider"></div>
  <div class="cover-footer">Generated by Agent D • Powered by AI</div>
</div>

<div class="toc-container">
  <div class="toc-header">
    <h2 class="toc-title">สารบัญ (Table of Contents)</h2>
    <div class="toc-divider"></div>
  </div>
  <table class="toc-table">
`;

// Process Data & Build TOC
const chaptersData = results.map((chap, index) => {
    const props = chap.properties || {};
    const chapNo = props['Chapter No.']?.number ?? (index + 1);

    let rawTitle = props['Chapter Title']?.title?.[0]?.plain_text || "Untitled";
    let cleanTitle = cleanChapterTitle(rawTitle);

    const rawImgUrl = props['Image 1 URL']?.rich_text?.[0]?.plain_text || 
                      props['Chapter Image']?.files?.[0]?.file?.url || 
                      props['Chapter Image']?.files?.[0]?.external?.url || "";
    const imgUrl = getDirectImageUrl(rawImgUrl);

    const contentRich = props['Content(HTML)']?.rich_text || [];
    let rawBody = contentRich.map(c => c.plain_text).join("");
    let body = rawBody;
    if (!rawBody.trim().startsWith("<")) {
        body = rawBody.split(/\n/).map(l => l.trim() ? `<p>${l}</p>` : "").join("");
    }
    body = cleanContentBody(body, cleanTitle, chapNo);
    body = transformCrossReferences(body, results);

    const keyTakeaways = props['Key Takeaways']?.rich_text?.[0]?.plain_text || "";
    const keyTerminology = props['Key Terminology']?.rich_text?.[0]?.plain_text || "";

    const chapLabel = chapNo === 0 ? "บทนำ" : `บทที่ ${chapNo}`;

    // Add to TOC Table
    fullHtml += `
    <tr class="toc-row">
      <td class="toc-num"><b>${chapLabel}</b></td>
      <td class="toc-text"><a href="#chap_${chapNo}" style="text-decoration: none; color: #1e293b;">${cleanTitle}</a></td>
      <td style="border-bottom: 1px dotted #94a3b8; width: 35%;"></td>
    </tr>
    `;

    return { 
      chapterNo: chapNo, 
      label: chapLabel,
      title: cleanTitle, 
      imgUrl, 
      body, 
      keyTakeaways,
      keyTerminology,
      id: `chap_${chapNo}` 
    };
});

fullHtml += `</table></div>`;

// เติมเนื้อหาแต่ละบท
chaptersData.forEach(c => {
    let imgHtml = "";
    if (c.imgUrl && c.imgUrl.startsWith("http")) {
        imgHtml = `
        <figure>
          <img src="${c.imgUrl}" width="600" alt="${c.title}">
          <figcaption>ภาพประกอบ ${c.label}: ${c.title}</figcaption>
        </figure>
        `;
    }

    let terminologyHtml = "";
    if (c.keyTerminology) {
        terminologyHtml = `
        <div class="key-terms-box">
          <div style="font-weight: bold; color: #15803d; margin-bottom: 6px;">📖 คลังคำศัพท์สำคัญประจำบท (Key Terminology)</div>
          <div>${c.keyTerminology.replace(/\n/g, '<br>')}</div>
        </div>
        `;
    }

    let takeawaysHtml = "";
    if (c.keyTakeaways) {
        takeawaysHtml = `
        <div class="takeaways-box">
          <div class="takeaways-title">💡 สรุปประเด็นสำคัญ (Key Takeaways)</div>
          <div class="takeaways-content">${c.keyTakeaways.replace(/\n/g, '<br>')}</div>
        </div>
        `;
    }

    fullHtml += `
    <div id="${c.id}" class="chapter-wrapper">
        <div class="chapter-header">
            <div class="chapter-badge">${c.label}</div>
            <h1 class="chapter-title">${c.title}</h1>
            <div class="chapter-rule"></div>
        </div>
        ${imgHtml}
        ${c.body}
        ${terminologyHtml}
        ${takeawaysHtml}
        <div class="ornament">❖ ❖ ❖</div>
    </div>
    `;
});

fullHtml += `</body></html>`;

// Return Binary
const fileName = `Book_Export_${Date.now()}.html`;
const buffer = Buffer.from(fullHtml, 'utf8');
const base64String = buffer.toString('base64');

return {
  json: { fileName },
  binary: {
    data: {
      data: base64String,
      mimeType: "text/html",
      fileName: fileName
    }
  }
};
